use axum::{body::Body, extract::{Path, Query, State}, http::{HeaderMap, StatusCode}, response::{IntoResponse, Response}, routing::{get, post, put, delete}, Json, Router};
use base64::{engine::general_purpose::STANDARD, Engine};
use scraper::{Html, Selector};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{collections::HashMap, sync::{Arc, Mutex}};
use argon2::{Argon2, PasswordHash, PasswordHasher, PasswordVerifier};
use argon2::password_hash::SaltString;
use rand::rngs::OsRng;
use jsonwebtoken::{decode, encode, DecodingKey, EncodingKey, Header, Validation};
use rusqlite::{params, Connection};
use uuid::Uuid;
use tower_http::cors::CorsLayer;

const BASE: &str = "https://otakudesu.blog";
const AJAX: &str = "https://otakudesu.blog/wp-admin/admin-ajax.php";
const UA: &str = "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/120 Safari/537.36";
#[derive(Clone)] struct AppState { client: reqwest::Client, db: Arc<Mutex<Connection>>, jwt: Arc<Vec<u8>> }
#[derive(Deserialize)] struct Page { page: Option<u32> }
#[derive(Deserialize)] struct Search { q: String, limit: Option<usize> }
#[derive(Deserialize)] struct UrlQuery { url: String }
#[derive(Deserialize)] struct EmbedQuery { id: u64, i: Option<u64>, q: Option<String> }
#[derive(Deserialize)] struct Credentials { username: String, password: String }
#[derive(Deserialize)] struct BookmarkInput { anime_url: String, title: String, image: Option<String> }
#[derive(Deserialize)] struct HistoryInput { episode_url: String, anime_url: Option<String>, title: String, episode: Option<String>, position_seconds: u64, duration_seconds: Option<u64> }
#[derive(Deserialize)] struct AuthHeader { authorization: Option<String> }
#[derive(Serialize, Deserialize)] struct Claims { sub: String, exp: usize }
#[derive(Serialize)] struct ApiError { ok: bool, error: String }
fn err(msg: impl Into<String>) -> (StatusCode, Json<Value>) { (StatusCode::INTERNAL_SERVER_ERROR, Json(json!({"ok":false,"error":msg.into()}))) }
fn init_db(c:&Connection)->Result<(),String>{c.execute_batch("CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS bookmarks(user_id TEXT NOT NULL,anime_url TEXT NOT NULL,title TEXT NOT NULL,image TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,anime_url));CREATE TABLE IF NOT EXISTS history(user_id TEXT NOT NULL,episode_url TEXT NOT NULL,anime_url TEXT,title TEXT NOT NULL,episode TEXT,position_seconds INTEGER NOT NULL DEFAULT 0,duration_seconds INTEGER,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,episode_url));").map_err(|e|e.to_string())}
fn token(s:&AppState,user:&str)->Result<String,String>{encode(&Header::default(),&Claims{sub:user.to_string(),exp:usize::MAX},&EncodingKey::from_secret(&s.jwt)).map_err(|e|e.to_string())}
fn user(s:&AppState,a:&str)->Result<String,String>{let t=a.strip_prefix("Bearer ").ok_or("Token tidak valid")?;decode::<Claims>(t,&DecodingKey::from_secret(&s.jwt),&Validation::default()).map(|x|x.claims.sub).map_err(|_|"Token tidak valid".into())}
fn hash(p:&str)->Result<String,String>{let salt=SaltString::generate(&mut OsRng);Argon2::default().hash_password(p.as_bytes(),&salt).map(|x|x.to_string()).map_err(|e|e.to_string())}
fn verify(h:&str,p:&str)->bool{PasswordHash::new(h).map(|x|Argon2::default().verify_password(p.as_bytes(),&x).is_ok()).unwrap_or(false)}
fn sel(s: &str) -> Selector { Selector::parse(s).unwrap() }
fn text(el: scraper::ElementRef) -> String { el.text().collect::<Vec<_>>().join(" ").split_whitespace().collect::<Vec<_>>().join(" ") }
async fn fetch(state: &AppState, url: &str) -> Result<Html, String> { let r=state.client.get(url).header("User-Agent",UA).header("Referer",BASE).send().await.map_err(|e|e.to_string())?; if !r.status().is_success(){return Err(format!("upstream HTTP {}",r.status()))} Ok(Html::parse_document(&r.text().await.map_err(|e|e.to_string())?)) }
fn absolute(v: Option<&str>) -> String { v.unwrap_or("").to_string() }
fn anime_card(item: scraper::ElementRef) -> Value { let a=item.select(&sel(".col-anime-title a[href]")).next(); let image=item.select(&sel(".col-anime-cover img[src], img[src]")).next().and_then(|x|x.value().attr("src")).unwrap_or_default(); json!({"title":a.map(|x|text(x)).unwrap_or_default(),"url":a.and_then(|x|x.value().attr("href")).unwrap_or_default(),"image":image,"studio":item.select(&sel(".col-anime-studio")).next().map(text).unwrap_or_default(),"episodes":item.select(&sel(".col-anime-eps")).next().map(text).unwrap_or_default(),"rating":item.select(&sel(".col-anime-rating")).next().map(text).unwrap_or_default(),"genres":item.select(&sel(".col-anime-genre")).next().map(text).unwrap_or_default()}) }
fn has_next_page(h:&Html,page:u32)->bool { h.select(&sel(".pagination a[href]")).any(|a| { let href=a.value().attr("href").unwrap_or(""); let n=href.trim_end_matches('/').rsplit("/page/").next().and_then(|x|x.parse::<u32>().ok()); n.map(|v|v>page).unwrap_or_else(||text(a).to_lowercase().contains("berikutnya")||text(a).to_lowercase().contains("next")) }) }
async fn root()->Response{let html=r#"<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OtakuDesu API Rust Docs</title><style>:root{color-scheme:dark;font-family:Inter,system-ui,sans-serif;background:#0b1020;color:#e8edf7}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#0b1020,#121b35);min-height:100vh}.wrap{max-width:1100px;margin:auto;padding:48px 22px}.hero{padding:34px;border:1px solid #263457;border-radius:24px;background:#121a31;box-shadow:0 20px 60px #0005}.eyebrow{color:#78a7ff;font-weight:700;letter-spacing:.12em;text-transform:uppercase;font-size:12px}h1{font-size:clamp(30px,5vw,56px);margin:12px 0}p{color:#aebbd4;line-height:1.7}.badge{display:inline-block;padding:6px 10px;border-radius:999px;background:#173d36;color:#7ce0b1;font-size:12px;font-weight:700}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px;margin-top:24px}.card{border:1px solid #263457;border-radius:16px;background:#11192e;padding:20px}.method{color:#7ce0b1;font:700 13px ui-monospace,monospace}.path{font:700 17px ui-monospace,monospace;color:#fff;margin:9px 0;word-break:break-word}.desc{font-size:14px;margin:0 0 14px}.try{display:inline-block;color:#91b8ff;text-decoration:none;font-size:13px}.try:hover{text-decoration:underline}.code{margin-top:28px;padding:20px;border-radius:16px;background:#080d19;border:1px solid #202d4c;color:#b9d2ff;overflow:auto;font:13px/1.6 ui-monospace,monospace}footer{margin-top:30px;color:#71809d;font-size:13px}@media(max-width:600px){.wrap{padding:24px 14px}.hero{padding:24px}}</style></head><body><main class="wrap"><section class="hero"><div class="eyebrow">NanoStream backend</div><h1>OtakuDesu API</h1><p>REST API async berbasis Rust untuk katalog anime, episode, streaming mirror, download link, dan thumbnail proxy.</p><span class="badge">v1.0.0 · CORS enabled</span></section><section class="grid"><article class="card"><div class="method">GET</div><div class="path">/api/search?q=frieren</div><p class="desc">Cari anime berdasarkan judul.</p><a class="try" href="/api/search?q=frieren" target="_blank">Try endpoint →</a></article><article class="card"><div class="method">GET</div><div class="path">/api/ongoing?page=1</div><p class="desc">Daftar anime ongoing dan episode terbaru.</p><a class="try" href="/api/ongoing?page=1" target="_blank">Try endpoint →</a></article><article class="card"><div class="method">GET</div><div class="path">/api/complete?page=1</div><p class="desc">Daftar anime yang sudah selesai.</p><a class="try" href="/api/complete?page=1" target="_blank">Try endpoint →</a></article><article class="card"><div class="method">GET</div><div class="path">/api/genres</div><p class="desc">Daftar semua genre anime.</p><a class="try" href="/api/genres" target="_blank">Try endpoint →</a></article><article class="card"><div class="method">GET</div><div class="path">/api/genre/{slug}?page=1</div><p class="desc">Anime berdasarkan genre, dengan pagination.</p><a class="try" href="/api/genre/action?page=1" target="_blank">Try action →</a></article><article class="card"><div class="method">GET</div><div class="path">/api/detail?url=...</div><p class="desc">Metadata anime dan daftar episodenya.</p><a class="try" href="/api/detail?url=https%3A%2F%2Fotakudesu.blog%2Fanime%2Fsousou-frieren-s2-sub-indo%2F" target="_blank">Try endpoint →</a></article><article class="card"><div class="method">GET</div><div class="path">/api/episode?url=...</div><p class="desc">Embed player, mirror, download, Previous, dan Next.</p><a class="try" href="/api/episode?url=https%3A%2F%2Fotakudesu.blog%2Fepisode%2Fknh-s3-episode-1-sub-indo%2F" target="_blank">Try endpoint →</a></article><article class="card"><div class="method">GET</div><div class="path">/api/embed?id=&amp;i=&amp;q=</div><p class="desc">Resolve mirror menjadi URL embed player.</p><a class="try" href="/api/embed?id=206012&amp;i=0&amp;q=480p" target="_blank">Try endpoint →</a></article><article class="card"><div class="method">GET</div><div class="path">/api/image?url=...</div><p class="desc">Proxy thumbnail dengan cache 1 hari.</p><a class="try" href="/api/image?url=https%3A%2F%2Fotakudesu.blog%2Fwp-content%2Fuploads%2F2026%2F01%2F154528.jpg" target="_blank">Try endpoint →</a></article></section><pre class="code">Base URL: http://localhost:8686
Response: {"ok":true,"data":...}
Frontend: NanoStream</pre><footer>OtakuDesu API Rust · Axum · Tokio · Reqwest · Scraper</footer></main></body></html>"#;Response::builder().status(StatusCode::OK).header("content-type","text/html; charset=utf-8").body(Body::from(html)).unwrap()}
async fn image(State(s):State<Arc<AppState>>,Query(q):Query<UrlQuery>)->Response{if !q.url.starts_with(BASE){return err("URL gambar tidak valid").into_response()}match s.client.get(&q.url).header("User-Agent",UA).send().await{Ok(r)=>{let ct=r.headers().get("content-type").and_then(|x|x.to_str().ok()).unwrap_or("image/jpeg").to_string();match r.bytes().await{Ok(b)=>Response::builder().status(StatusCode::OK).header("content-type",ct).header("cache-control","public, max-age=86400").body(Body::from(b)).unwrap(),Err(e)=>err(e.to_string()).into_response()}},Err(e)=>err(e.to_string()).into_response()}}
async fn register(State(s):State<Arc<AppState>>,Json(c):Json<Credentials>)->impl IntoResponse{if c.username.len()<3||c.password.len()<6{return err("Username minimal 3 karakter dan password minimal 6 karakter").into_response()}let id=Uuid::new_v4().to_string();let h=match hash(&c.password){Ok(v)=>v,Err(e)=>return err(e).into_response()};let db=s.db.lock().unwrap();match db.execute("INSERT INTO users(id,username,password_hash) VALUES(?1,?2,?3)",params![id,c.username,h]){Ok(_)=>Json(json!({"ok":true,"token":token(&s,&id).unwrap(),"username":c.username})).into_response(),Err(_)=>err("Username sudah digunakan").into_response()}}
async fn login(State(s):State<Arc<AppState>>,Json(c):Json<Credentials>)->impl IntoResponse{let db=s.db.lock().unwrap();let row=db.query_row("SELECT id,password_hash FROM users WHERE username=?1",params![c.username],|r|Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?)));match row{Ok((id,h)) if verify(&h,&c.password)=>Json(json!({"ok":true,"token":token(&s,&id).unwrap()})).into_response(),_=>err("Username atau password salah").into_response()}}
fn auth(s:&AppState,h:&HeaderMap)->Result<String,(StatusCode,Json<Value>)>{let v=h.get("authorization").and_then(|x|x.to_str().ok()).ok_or_else(||(StatusCode::UNAUTHORIZED,Json(json!({"ok":false,"error":"Login diperlukan"}))))?;user(s,v).map_err(|e|(StatusCode::UNAUTHORIZED,Json(json!({"ok":false,"error":e}))))}
async fn bookmarks(State(s):State<Arc<AppState>>,h:HeaderMap)->impl IntoResponse{let uid=match auth(&s,&h){Ok(v)=>v,Err(e)=>return e.into_response()};let db=s.db.lock().unwrap();let mut st=db.prepare("SELECT anime_url,title,image,created_at FROM bookmarks WHERE user_id=?1 ORDER BY created_at DESC").unwrap();let rows=st.query_map(params![uid],|r|Ok(json!({"anime_url":r.get::<_,String>(0)?,"title":r.get::<_,String>(1)?,"image":r.get::<_,Option<String>>(2)?,"created_at":r.get::<_,String>(3)?}))).unwrap().filter_map(Result::ok).collect::<Vec<_>>();Json(json!({"ok":true,"data":rows})).into_response()}
async fn bookmark_add(State(s):State<Arc<AppState>>,h:HeaderMap,Json(x):Json<BookmarkInput>)->impl IntoResponse{let uid=match auth(&s,&h){Ok(v)=>v,Err(e)=>return e.into_response()};let db=s.db.lock().unwrap();match db.execute("INSERT OR REPLACE INTO bookmarks(user_id,anime_url,title,image) VALUES(?1,?2,?3,?4)",params![uid,x.anime_url,x.title,x.image]){Ok(_)=>Json(json!({"ok":true})).into_response(),Err(e)=>err(e.to_string()).into_response()}}
async fn bookmark_delete(State(s):State<Arc<AppState>>,h:HeaderMap,Query(q):Query<UrlQuery>)->impl IntoResponse{let uid=match auth(&s,&h){Ok(v)=>v,Err(e)=>return e.into_response()};let db=s.db.lock().unwrap();match db.execute("DELETE FROM bookmarks WHERE user_id=?1 AND anime_url=?2",params![uid,q.url]){Ok(_)=>Json(json!({"ok":true})).into_response(),Err(e)=>err(e.to_string()).into_response()}}
async fn history(State(s):State<Arc<AppState>>,h:HeaderMap)->impl IntoResponse{let uid=match auth(&s,&h){Ok(v)=>v,Err(e)=>return e.into_response()};let db=s.db.lock().unwrap();let mut st=db.prepare("SELECT episode_url,anime_url,title,episode,position_seconds,duration_seconds,updated_at FROM history WHERE user_id=?1 ORDER BY updated_at DESC").unwrap();let rows=st.query_map(params![uid],|r|Ok(json!({"episode_url":r.get::<_,String>(0)?,"anime_url":r.get::<_,Option<String>>(1)?,"title":r.get::<_,String>(2)?,"episode":r.get::<_,Option<String>>(3)?,"position_seconds":r.get::<_,u64>(4)?,"duration_seconds":r.get::<_,Option<u64>>(5)?,"updated_at":r.get::<_,String>(6)?}))).unwrap().filter_map(Result::ok).collect::<Vec<_>>();Json(json!({"ok":true,"data":rows})).into_response()}
async fn history_save(State(s):State<Arc<AppState>>,h:HeaderMap,Json(x):Json<HistoryInput>)->impl IntoResponse{let uid=match auth(&s,&h){Ok(v)=>v,Err(e)=>return e.into_response()};let db=s.db.lock().unwrap();match db.execute("INSERT INTO history(user_id,episode_url,anime_url,title,episode,position_seconds,duration_seconds) VALUES(?1,?2,?3,?4,?5,?6,?7) ON CONFLICT(user_id,episode_url) DO UPDATE SET position_seconds=excluded.position_seconds,duration_seconds=excluded.duration_seconds,updated_at=CURRENT_TIMESTAMP",params![uid,x.episode_url,x.anime_url,x.title,x.episode,x.position_seconds,x.duration_seconds]){Ok(_)=>Json(json!({"ok":true})).into_response(),Err(e)=>err(e.to_string()).into_response()}}
async fn search(State(s):State<Arc<AppState>>,Query(q):Query<Search>)->impl IntoResponse{let url=format!("{BASE}/?s={}&post_type=anime",urlencoding::encode(&q.q));match fetch(&s,&url).await{Ok(h)=>{let mut out=vec![];for li in h.select(&sel("ul.chivsrc > li")).take(q.limit.unwrap_or(12)){if let Some(a)=li.select(&sel("h2 > a[href]")).next(){let img=li.select(&sel("img")).next().and_then(|x|x.value().attr("src")).unwrap_or("");let sets=li.select(&sel(".set")).map(text).collect::<Vec<_>>().join(" ");out.push(json!({"title":text(a),"url":a.value().attr("href").unwrap_or(""),"image":img,"genres":sets,"status":"","rating":""}));}} Json(json!({"ok":true,"count":out.len(),"data":out})).into_response()},Err(e)=>err(e).into_response()}}
async fn ongoing(State(s):State<Arc<AppState>>,Query(p):Query<Page>)->impl IntoResponse{let page=p.page.unwrap_or(1);let url=if page==1{format!("{BASE}/ongoing-anime/")}else{format!("{BASE}/ongoing-anime/page/{page}/")}; match fetch(&s,&url).await{Ok(h)=>{let mut out=vec![];for li in h.select(&sel("div.venz ul > li")){let d=li.select(&sel(".detpost")).next();if let Some(d)=d{let a=d.select(&sel(".thumb a[href]")).next();let im=d.select(&sel(".thumbz img")).next();out.push(json!({"title":im.and_then(|x|x.value().attr("alt")).unwrap_or_else(||a.map(|x|x.value().attr("title").unwrap_or("")).unwrap_or("")),"url":a.and_then(|x|x.value().attr("href")).unwrap_or(""),"image":im.and_then(|x|x.value().attr("src")).unwrap_or(""),"episode":d.select(&sel(".epz")).next().map(text).unwrap_or_default(),"day":d.select(&sel(".epztipe")).next().map(text).unwrap_or_default(),"date":d.select(&sel(".newnime")).next().map(text).unwrap_or_default()}));}}Json(json!({"ok":true,"page":page,"count":out.len(),"data":out})).into_response()},Err(e)=>err(e).into_response()}}
async fn complete(State(s):State<Arc<AppState>>,Query(p):Query<Page>)->impl IntoResponse{let page=p.page.unwrap_or(1);let url=if page==1{format!("{BASE}/complete-anime/")}else{format!("{BASE}/complete-anime/page/{page}/")}; match fetch(&s,&url).await{Ok(h)=>{let out=h.select(&sel("div.venz ul > li")).filter_map(|li|li.select(&sel(".detpost")).next()).map(|d|{let a=d.select(&sel(".thumb a[href]")).next();let im=d.select(&sel(".thumbz img")).next();json!({"title":im.and_then(|x|x.value().attr("alt")).unwrap_or_else(||a.map(|x|x.value().attr("title").unwrap_or("")).unwrap_or("")),"url":a.and_then(|x|x.value().attr("href")).unwrap_or(""),"image":im.and_then(|x|x.value().attr("src")).unwrap_or(""),"episodes":d.select(&sel(".epz")).next().map(text).unwrap_or_default(),"rating":d.select(&sel(".epztipe")).next().map(text).unwrap_or_default(),"date":d.select(&sel(".newnime")).next().map(text).unwrap_or_default()})}).collect::<Vec<_>>();Json(json!({"ok":true,"page":page,"count":out.len(),"data":out})).into_response()},Err(e)=>err(e).into_response()}}
async fn genres(State(s):State<Arc<AppState>>)->impl IntoResponse{match fetch(&s,&format!("{BASE}/genre-list/")).await{Ok(h)=>{let out=h.select(&sel(".genres a[href]")).map(|a|{let u=a.value().attr("href").unwrap_or("");json!({"name":text(a),"slug":u.trim_end_matches('/').rsplit('/').next().unwrap_or(""),"url":u})}).collect::<Vec<_>>();Json(json!({"ok":true,"count":out.len(),"data":out})).into_response()},Err(e)=>err(e).into_response()}}
async fn genre(Path(slug):Path<String>,State(s):State<Arc<AppState>>,Query(p):Query<Page>)->impl IntoResponse{let page=p.page.unwrap_or(1);let url=if page==1{format!("{BASE}/genres/{slug}/")}else{format!("{BASE}/genres/{slug}/page/{page}/")};match fetch(&s,&url).await{Ok(h)=>{let out=h.select(&sel(".col-anime-con")).map(anime_card).collect::<Vec<_>>();Json(json!({"ok":true,"slug":slug,"page":page,"count":out.len(),"has_next":has_next_page(&h,page),"data":out})).into_response()},Err(e)=>err(e).into_response()}}
async fn detail(State(s):State<Arc<AppState>>,Query(q):Query<UrlQuery>)->impl IntoResponse{if !q.url.contains("otakudesu.blog"){return err("URL harus dari otakudesu.blog").into_response()}match fetch(&s,&q.url).await{Ok(h)=>{let mut info=serde_json::Map::new();for p in h.select(&sel(".infozingle p, .infozin p")){let raw=text(p);let spans=p.select(&sel("span")).map(text).collect::<Vec<_>>();let parts=if spans.len()>=2{spans}else{vec![raw]};for part in parts{if let Some((k,v))=part.split_once(':'){info.insert(k.trim().to_string(),json!(v.trim()));}}}let genres=h.select(&sel(".infozingle a[href*='/genres/'], .infozin a[href*='/genres/']")).map(text).collect::<Vec<_>>();if !genres.is_empty(){info.insert("Genre".into(),json!(genres.join(", ")));}let img=h.select(&sel(".fotoanime img")).next().and_then(|x|x.value().attr("src")).unwrap_or("");info.insert("image".into(),json!(img));let episode_lists=h.select(&sel(".episodelist")).filter(|x|text(*x).contains("Episode List")).collect::<Vec<_>>();let eps=episode_lists.iter().flat_map(|x|x.select(&sel("ul li")).collect::<Vec<_>>()).filter_map(|li|{let a=li.select(&sel("a[href]")).next()?;let title=text(a);let num=title.split("Episode ").nth(1).and_then(|x|x.split_whitespace().next()).and_then(|x|x.parse::<u64>().ok()).unwrap_or(0);json_from_ep(num,&title,a.value().attr("href").unwrap_or(""),li.select(&sel(".zeebr")).next().map(text).unwrap_or_default())}).collect::<Vec<_>>();Json(json!({"ok":true,"data":{"info":info,"episodes":eps,"batch":[]}})).into_response()},Err(e)=>err(e).into_response()}}
fn json_from_ep(num:u64,title:&str,url:&str,date:String)->Option<Value>{Some(json!({"num":num,"title":title,"url":url,"date":date}))}
async fn episode(State(s):State<Arc<AppState>>,Query(q):Query<UrlQuery>)->impl IntoResponse{if !q.url.contains("otakudesu.blog"){return err("URL harus dari otakudesu.blog").into_response()}match fetch(&s,&q.url).await{Ok(h)=>{let title=h.select(&sel("h1.posttl")).next().map(text).unwrap_or_default();let embed=h.select(&sel(".responsive-embed-stream iframe")).next().and_then(|x|x.value().attr("src")).unwrap_or("");let prev=h.select(&sel(".flir a")).find(|a|{let t=text(*a).to_lowercase();let title=a.value().attr("title").unwrap_or("").to_lowercase();t.contains("prev")||title.contains("sebelumnya")||title.contains("previous")}).and_then(|a|a.value().attr("href")).unwrap_or("");let next=h.select(&sel(".flir a")).find(|a|{let t=text(*a).to_lowercase();let title=a.value().attr("title").unwrap_or("").to_lowercase();t.contains("next")||title.contains("selanjutnya")||title.contains("next")}).and_then(|a|a.value().attr("href")).unwrap_or("");let all=h.select(&sel(".flir a")).find(|a|text(*a).to_lowercase().contains("all episodes")).and_then(|a|a.value().attr("href")).unwrap_or("");let mut mirrors=serde_json::Map::new();for ul in h.select(&sel(".mirrorstream ul")){let ql=ul.value().classes().find(|x|x.starts_with('m')).unwrap_or("unknown").trim_start_matches('m').to_string();let arr=ul.select(&sel("a[data-content]")).filter_map(|a|{let data=a.value().attr("data-content")?;let decoded=STANDARD.decode(data).ok()?;let v:Value=serde_json::from_slice(&decoded).ok()?;Some(json!({"name":text(a),"post_id":v["id"],"mirror_index":v["i"],"quality":v["q"]}))}).collect::<Vec<_>>();mirrors.insert(ql,json!(arr));}let downloads=h.select(&sel(".download li")).map(|li|{let links=li.select(&sel("a[href]")).map(|a|json!({"name":text(a),"url":a.value().attr("href").unwrap_or("")})).collect::<Vec<_>>();json!({"quality":li.select(&sel("strong")).next().map(text).unwrap_or_default(),"size":li.select(&sel("i")).next().map(text).unwrap_or_default(),"links":links})}).collect::<Vec<_>>();Json(json!({"ok":true,"data":{"title":title,"default_embed":embed,"mirrors":mirrors,"downloads":downloads,"nav":{"prev":prev,"next":next,"all_episodes":all},"episode_list":[]}})).into_response()},Err(e)=>err(e).into_response()}}
async fn embed(State(s):State<Arc<AppState>>,Query(q):Query<EmbedQuery>)->impl IntoResponse{let n=s.client.post(AJAX).header("User-Agent",UA).form(&[("action","aa1208d27f29ca340c92c66d1926f13f")]).send().await;let nonce=match n{Ok(x)=>match x.json::<Value>().await{Ok(v)=>v["data"].as_str().unwrap_or("").to_string(),Err(e)=>return err(e.to_string()).into_response()},Err(e)=>return err(e.to_string()).into_response()};let form=[("id",q.id.to_string()),("i",q.i.unwrap_or(0).to_string()),("q",q.q.unwrap_or_else(||"480p".to_string())),("nonce",nonce),("action","2a3505c93b0035d3f455df82bf976b84".to_string())];match s.client.post(AJAX).header("User-Agent",UA).form(&form).send().await{Ok(r)=>match r.json::<Value>().await{Ok(v)=>{let b=v["data"].as_str().unwrap_or("");let html=STANDARD.decode(b).ok().and_then(|x|String::from_utf8(x).ok()).unwrap_or_default();let re=html.split("src=\"").nth(1).and_then(|x|x.split('\"').next()).unwrap_or("");Json(json!({"ok":true,"data":{"embed_url":re}})).into_response()},Err(e)=>err(e.to_string()).into_response()},Err(e)=>err(e.to_string()).into_response()}}
#[tokio::main] async fn main(){tracing_subscriber::fmt::init();let client=reqwest::Client::builder().gzip(true).brotli(true).deflate(true).build().unwrap();let db=Connection::open("nanostream.sqlite3").unwrap();init_db(&db).unwrap();let secret=std::env::var("NANOSTREAM_JWT_SECRET").unwrap_or_else(|_|Uuid::new_v4().to_string());let state=Arc::new(AppState{client,db:Arc::new(Mutex::new(db)),jwt:Arc::new(secret.into_bytes())});let app=Router::new().route("/",get(root)).route("/api/search",get(search)).route("/api/ongoing",get(ongoing)).route("/api/complete",get(complete)).route("/api/genres",get(genres)).route("/api/genre/{slug}",get(genre)).route("/api/detail",get(detail)).route("/api/episode",get(episode)).route("/api/embed",get(embed)).route("/api/image",get(image)).route("/api/auth/register",post(register)).route("/api/auth/login",post(login)).route("/api/bookmarks",get(bookmarks).post(bookmark_add)).route("/api/bookmarks/remove",delete(bookmark_delete)).route("/api/history",get(history).post(history_save)).layer(CorsLayer::permissive()).with_state(state);let listener=tokio::net::TcpListener::bind("0.0.0.0:8686").await.unwrap();axum::serve(listener,app).await.unwrap();}